<?php
namespace Tests\Feature;
use App\Models\TenantRegistrationRequest;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Str;use Laravel\Sanctum\Sanctum;use Tests\TestCase;
class TenantRegistrationCrudTest extends TestCase
{
 use RefreshDatabase;
 public function test_super_admin_can_search_update_and_archive_unapproved_registration():void{$super=User::create(['public_id'=>(string)Str::ulid(),'identity_region'=>'ap-south-1','first_name'=>'Super','display_name'=>'Super','email_encrypted'=>'encrypted','email_hash'=>hash('sha256',Str::random()),'email_masked'=>'s***@example.com','phone_encrypted'=>'encrypted','phone_hash'=>hash('sha256',Str::random()),'phone_masked'=>'+91 ******1234','status'=>'active','registered_via'=>'test','registration_started_at'=>now()]);config(['ai_lms.super_admin_public_ids'=>[$super->public_id]]);$applicant=User::create(['public_id'=>(string)Str::ulid(),'identity_region'=>'ap-south-1','first_name'=>'Applicant','display_name'=>'Applicant','email_encrypted'=>'encrypted','email_hash'=>hash('sha256',Str::random()),'email_masked'=>'a***@example.com','phone_encrypted'=>'encrypted','phone_hash'=>hash('sha256',Str::random()),'phone_masked'=>'+91 ******5678','status'=>'pending_approval','registered_via'=>'self','registration_started_at'=>now()]);$registration=TenantRegistrationRequest::create(['public_id'=>(string)Str::ulid(),'applicant_user_id'=>$applicant->id,'registration_token_hash'=>hash('sha256',Str::random()),'institution_name'=>'Old Academy','requested_slug'=>'old-academy','constitution_type'=>'company','home_region'=>'ap-south-1','country_code'=>'IN','timezone'=>'Asia/Kolkata','default_language'=>'en','default_currency'=>'INR','status'=>'submitted']);Sanctum::actingAs($super);$this->getJson('/api/v1/admin/tenant-registrations?search=Old')->assertOk()->assertJsonCount(1,'data');$this->patchJson('/api/v1/admin/tenant-registrations/'.$registration->public_id,['institution_name'=>'New Academy'])->assertOk()->assertJsonPath('data.institution_name','New Academy');$this->deleteJson('/api/v1/admin/tenant-registrations/'.$registration->public_id)->assertOk();$this->assertSoftDeleted('tenant_registration_requests',['id'=>$registration->id]);}
}
